import urllib.request
from bs4 import BeautifulSoup
import re

all_links = set()
for section in ['fruits', 'vegetables', 'nuts', 'specialty-crops']:
    try:
        url = f'https://www.ams.usda.gov/grades-standards/{section}'
        html = urllib.request.urlopen(url).read().decode('utf-8')
        soup = BeautifulSoup(html, 'html.parser')
        for a in soup.find_all('a'):
            href = a.get('href', '')
            if '/grades-standards/' in href:
                all_links.add((a.get_text().strip(), href))
    except Exception as e:
        print(section, e)

print('Total links collected:', len(all_links))
# Let's filter for anything related to Dehydrated, Apples, Grapefruit, Orange
for title, href in sorted(all_links):
    tl = title.lower()
    if any(k in tl for k in ['dehydrated', 'grapefruit', 'orange', 'apple']):
        print(f'{title} : {href}')
