import urllib.request
from bs4 import BeautifulSoup

all_items = {}
for cat in ['fruits', 'vegetables', 'nuts', 'specialty-crops', 'processed-fruits-and-vegetables']:
    page = 0
    while True:
        url = f'https://www.ams.usda.gov/grades-standards/{cat}?page={page}'
        try:
            html = urllib.request.urlopen(url).read().decode('utf-8')
            soup = BeautifulSoup(html, 'html.parser')
            links = []
            for a in soup.find_all('a'):
                href = a.get('href', '')
                if '/grades-standards/' in href and not href.endswith((f'/{cat}', f'/{cat}?page={page}')):
                    txt = a.get_text().strip()
                    if txt and txt not in ['Fruits', 'Vegetables', 'Nuts']:
                        links.append((txt, href))
            if not links or all((t, h) in all_items for t, h in links):
                break
            for t, h in links:
                all_items[t] = h
            # Check if there's a next page
            if not soup.find('li', class_='pager__item--next'):
                break
            page += 1
        except Exception as e:
            # print(cat, page, e)
            break

print(f'Total items scraped: {len(all_items)}')
for t, h in sorted(all_items.items()):
    print(f'{t} --> {h}')
